from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    stack = []
    groups = []
    current_group = ""

    for char in paren_string:
        if char == "(":
            stack.append(char)
            current_group += char
        elif char == ")":
            if not stack:
                raise ValueError("Unbalanced parentheses in group: {}".format(current_group))
            stack.pop()
            current_group += char
            if not stack:
                groups.append(current_group)
                current_group = ""

    if stack:
        raise ValueError("Unbalanced parentheses in input string")

    return groups

