from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Step 1: Remove any spaces from the input string
    separate_strings = []  # Step 2: Initialize an empty list to store the separate strings
    stack = []  # Stack to keep track of open parentheses indices

    for i, char in enumerate(paren_string):
        if char == '(':
            stack.append(i)  # Push the index of open parenthesis to the stack
        elif char == ')':
            if stack:  # If stack is not empty
                start = stack.pop()  # Pop the index of the corresponding open parenthesis
                separate_strings.append(paren_string[start:i+1])  # Extract the group of balanced parentheses and add it to the list

    return separate_strings  # Step 6: Return the list of separate strings
